const stdout = $node["get_allocations"].json.stdout || $node["get_allocations"].json;
const ts = new Date().toLocaleString('tr-TR', { timeZone: 'Europe/Istanbul' });

let rows;

if (typeof stdout === 'string') {
  rows = JSON.parse(stdout);
